// Mobile menu toggle
(function() {
  var hamburger = document.getElementById('hamburger');
  var menu = document.getElementById('mobileMenu');
  var overlay = document.getElementById('mobileOverlay');
  var close = document.getElementById('mobileMenuClose');

  function openMenu() { menu.classList.add('open'); overlay.classList.add('active'); document.body.style.overflow = 'hidden'; }
  function closeMenu() { menu.classList.remove('open'); overlay.classList.remove('active'); document.body.style.overflow = ''; }

  hamburger.addEventListener('click', openMenu);
  close.addEventListener('click', closeMenu);
  overlay.addEventListener('click', closeMenu);
})();

// Autocomplete
(function() {
  var suggestions = [
    'Dentist', 'Primary Care', 'Dermatologist', 'Psychiatrist',
    'Eye Doctor', 'Orthopedic Surgeon', 'Cardiologist', 'Pediatrician',
    'Back pain', 'Skin rash', 'Flu symptoms', 'Annual checkup',
    'Dr. Sarah Chen', 'Dr. Michael Roberts', 'Dr. Emily Park'
  ];

  var input = document.getElementById('searchInput');
  var dropdown = document.getElementById('autocompleteDropdown');
  var activeIdx = -1;

  input.addEventListener('input', function() {
    var val = this.value.trim().toLowerCase();
    dropdown.innerHTML = '';
    activeIdx = -1;
    if (!val) { dropdown.classList.remove('visible'); return; }

    var matches = suggestions.filter(function(s) { return s.toLowerCase().indexOf(val) !== -1; });
    if (!matches.length) { dropdown.classList.remove('visible'); return; }

    matches.forEach(function(m, i) {
      var div = document.createElement('div');
      div.className = 'autocomplete-item';
      div.innerHTML = '<i class="ri-search-line"></i> <span>' + highlightMatch(m, val) + '</span>';
      div.addEventListener('mousedown', function(e) { e.preventDefault(); input.value = m; dropdown.classList.remove('visible'); });
      div.addEventListener('mouseenter', function() { setActive(i); });
      dropdown.appendChild(div);
    });
    dropdown.classList.add('visible');
  });

  input.addEventListener('keydown', function(e) {
    var items = dropdown.querySelectorAll('.autocomplete-item');
    if (!items.length) return;
    if (e.key === 'ArrowDown') { e.preventDefault(); setActive(activeIdx < items.length - 1 ? activeIdx + 1 : 0); }
    else if (e.key === 'ArrowUp') { e.preventDefault(); setActive(activeIdx > 0 ? activeIdx - 1 : items.length - 1); }
    else if (e.key === 'Enter' && activeIdx >= 0) { e.preventDefault(); input.value = items[activeIdx].textContent.trim(); dropdown.classList.remove('visible'); }
    else if (e.key === 'Escape') { dropdown.classList.remove('visible'); }
  });

  function setActive(idx) {
    var items = dropdown.querySelectorAll('.autocomplete-item');
    items.forEach(function(it) { it.classList.remove('active'); });
    activeIdx = idx;
    if (items[idx]) items[idx].classList.add('active');
  }

  function highlightMatch(text, query) {
    var re = new RegExp('(' + query.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + ')', 'gi');
    return text.replace(re, '<strong>$1</strong>');
  }

  document.addEventListener('click', function(e) {
    if (!input.parentElement.contains(e.target)) dropdown.classList.remove('visible');
  });
})();

// Specialty card clicks
(function() {
  var cards = document.querySelectorAll('.specialty-card');
  var input = document.getElementById('searchInput');
  cards.forEach(function(card) {
    card.addEventListener('click', function() {
      var specialty = this.getAttribute('data-specialty');
      input.value = specialty;
      input.scrollIntoView({ behavior: 'smooth' });
      input.focus();
    });
  });
})();
</script>
